// solve a single query brute
ll brute(const vector<ll>&a, int l,int r,ll L,ll R){
    ll cur=0,best=0;
    for(int i=l;i<=r;i++){
        if(a[i]>=L && a[i]<=R) cur+=a[i]; else cur+=0;
        if(cur<0) cur=0;
        if(cur>best) best=cur;
    }
    return best;
}

// Mo-based solver for a batch
vector<ll> solveMo(int n, const vector<ll>&a, vector<array<ll,4>> qs){
    int m=qs.size();
    vector<ll> ans(m,0);
    vector<ll> dist=a;
    sort(dist.begin(),dist.end());
    dist.erase(unique(dist.begin(),dist.end()),dist.end());
    int V=dist.size();
    vector<vector<int>> posOf(V);
    for(int i=0;i<n;i++){
        int id=lower_bound(dist.begin(),dist.end(),a[i])-dist.begin();
        posOf[id].push_back(i);
    }
    int N2=1; while(N2<n) N2<<=1;
    vector<Node> seg(2*N2, ID);
    for(int i=0;i<n;i++){
        ll v=a[i]; Node nd; nd.sum=v; nd.pref=nd.suff=nd.best=v>0?v:0; seg[N2+i]=nd;
    }
    for(int i=N2-1;i>=1;i--) seg[i]=mergeNode(seg[i<<1],seg[i<<1|1]);
    auto upd=[&](int pos,ll v){
        int i=N2+pos; Node nd; nd.sum=v; nd.pref=nd.suff=nd.best=v>0?v:0; seg[i]=nd;
        for(i>>=1;i;i>>=1) seg[i]=mergeNode(seg[i<<1],seg[i<<1|1]);
    };
    auto qry=[&](int l,int r){
        Node rl=ID,rr=ID; l+=N2; r+=N2+1;
        while(l<r){ if(l&1) rl=mergeNode(rl,seg[l++]); if(r&1) rr=mergeNode(seg[--r],rr); l>>=1; r>>=1; }
        return mergeNode(rl,rr);
    };
    struct Q{int lo,hi,l,r,id;};
    vector<Q> q2;
    for(int i=0;i<m;i++){
        ll L=qs[i][2],R=qs[i][3];
        int lo=lower_bound(dist.begin(),dist.end(),L)-dist.begin();
        int hi=upper_bound(dist.begin(),dist.end(),R)-dist.begin()-1;
        if(lo>hi){ans[i]=0;continue;}
        q2.push_back({lo,hi,(int)qs[i][0],(int)qs[i][1],i});
    }
    if(!q2.empty()){
        int Q=q2.size(); int SB=max(1,(int)(V/max(1.0,sqrt((double)Q))));
        sort(q2.begin(),q2.end(),[&](const Q&x,const Q&y){
            int bx=x.lo/SB,by=y.lo/SB;
            if(bx!=by) return bx<by;
            if(bx&1) return x.hi>y.hi; return x.hi<y.hi;
        });
        int cl=0,cr=-1;
        for(auto&q:q2){
            while(cr<q.hi){++cr; for(int p:posOf[cr]) upd(p,a[p]);}
            while(cl>q.lo){--cl; for(int p:posOf[cl]) upd(p,a[p]);}
            while(cr>q.hi){for(int p:posOf[cr]) upd(p,0);--cr;}
            while(cl<q.lo){for(int p:posOf[cl]) upd(p,0);++cl;}
            ans[q.id]=qry(q.l,q.r).best;
        }
    }
    return ans;
}

