typedef long long ll;

struct Node { ll sum, pref, suff, best; };
static const Node ID = {0,0,0,0};
inline Node mergeNode(const Node&a, const Node&b){
    Node c;
    c.sum = a.sum + b.sum;
    c.pref = max(a.pref, a.sum + b.pref);
    c.suff = max(b.suff, b.sum + a.suff);
    c.best = max(max(a.best, b.best), a.suff + b.pref);
    return c;
}

ll brute(const vector<ll>&a, int l,int r,ll L,ll R){
    ll cur=0,best=0;
    for(int i=l;i<=r;i++){
        if(a[i]>=L && a[i]<=R) cur+=a[i];
        if(cur<0) cur=0;
        if(cur>best) best=cur;
    }
    return best;
}

struct QD{int l,r,bl,br,id; ll L,R;};

vector<ll> solveBlock(int n, const vector<ll>&a, vector<array<ll,4>> qs){
    int m=qs.size();
    vector<ll> ans(m,0);
    const int B=8; // small for testing correctness
    int nb=(n+B-1)/B;
    vector<QD> qs2(m);
    for(int i=0;i<m;i++){
        int l=(int)qs[i][0], r=(int)qs[i][1];
        qs2[i]={l,r,l/B,r/B,i,qs[i][2],qs[i][3]};
    }
    vector<Node> acc(m, ID);
    // process each block
    for(int b=0;b<nb;b++){
        int bl0=b*B, br0=min(n,(b+1)*B)-1;
        int s=br0-bl0+1;
        // distinct values in block
        vector<ll> bv;
        for(int p=bl0;p<=br0;p++) bv.push_back(a[p]);
        sort(bv.begin(),bv.end()); bv.erase(unique(bv.begin(),bv.end()),bv.end());
        int d=bv.size();
        vector<vector<int>> rl(d);
        for(int p=bl0;p<=br0;p++){
            int rk=lower_bound(bv.begin(),bv.end(),a[p])-bv.begin();
            rl[rk].push_back(p-bl0);
        }
        // small seg tree
        int sb=1; while(sb<s) sb<<=1;
        vector<Node> segb(2*sb, ID);
        auto upd=[&](int pos,ll v){
            int i=sb+pos; Node nd; nd.sum=v; nd.pref=nd.suff=nd.best=v>0?v:0; segb[i]=nd;
            for(i>>=1;i;i>>=1) segb[i]=mergeNode(segb[i<<1],segb[i<<1|1]);
        };
        vector<Node> S((size_t)d*d, ID);
        for(int i=0;i<d;i++){
            fill(segb.begin(), segb.end(), ID);
            for(int j=i;j<d;j++){
                for(int pp: rl[j]) upd(pp, a[bl0+pp]);
                S[(size_t)i*d+j]=segb[1];
            }
        }
        // answer queries covering this block fully
        for(int qi=0; qi<m; qi++){
            if(qs2[qi].bl < b && b < qs2[qi].br){
                int i=lower_bound(bv.begin(),bv.end(),qs2[qi].L)-bv.begin();
                int j=upper_bound(bv.begin(),bv.end(),qs2[qi].R)-bv.begin()-1;
                Node nd=ID;
                if(i<=j) nd=S[(size_t)i*d+j];
                acc[qi]=mergeNode(acc[qi], nd);
            }
        }
    }
    // partials
    for(int qi=0; qi<m; qi++){
        int l=qs2[qi].l, r=qs2[qi].r, bl=qs2[qi].bl, br=qs2[qi].br; ll L=qs2[qi].L, R=qs2[qi].R;
        Node res=ID;
        if(bl==br){
            for(int p=l;p<=r;p++){
                ll v=(a[p]>=L && a[p]<=R)?a[p]:0;
                Node nd{v, v>0?v:0, v>0?v:0, v>0?v:0};
                res=mergeNode(res, nd);
            }
        } else {
            for(int p=l; p<=min(n,(bl+1)*B)-1; p++){
                ll v=(a[p]>=L && a[p]<=R)?a[p]:0;
                Node nd{v, v>0?v:0, v>0?v:0, v>0?v:0};
                res=mergeNode(res, nd);
            }
            res=mergeNode(res, acc[qi]);
            for(int p=br*B; p<=r; p++){
                ll v=(a[p]>=L && a[p]<=R)?a[p]:0;
                Node nd{v, v>0?v:0, v>0?v:0, v>0?v:0};
                res=mergeNode(res, nd);
            }
        }
        ans[qi]=res.best;
    }
    return ans;
}

